            transition: left 0.5s;
            transform: translateY(-50%);
        }

        .option-btn:hover::before {
            left: 100%;
        }

        .option-btn:hover {
            transform: translateX(8px) scale(1.02);
            box-shadow: var(--shadow-hover);
            background: var(--accent-hover);
        }

        .option-btn.pressed {
            transform: scale(0.98);
            transition: var(--transition-fast);
        }

        .option-btn:nth-child(1) { animation-delay: 0.1s; }
        .option-btn:nth-child(2) { animation-delay: 0.2s; }
        .option-btn:nth-child(3) { animation-delay: 0.3s; }
        .option-btn:nth-child(4) { animation-delay: 0.4s; }
        .option-btn:nth-child(5) { animation-delay: 0.5s; }

        .status-container {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 12px;
            margin: 24px 0;
        }

        .status-item {
            padding: 12px 16px;
            border-radius: var(--radius-small);
            font-size: 13px;
            text-align: center;
            backdrop-filter: var(--blur-default);
            transition: var(--transition-default);
            position: relative;
            overflow: hidden;
            background: var(--status-bg);
            opacity: 0;
        }

        .status-item.animate {
            animation: fadeIn var(--animation-duration) ease forwards;
        }

        .status-item::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(255, 255, 255, 0.1) 0%, transparent 70%);
            opacity: 0;
            transition: opacity 0.3s;
            transform: rotate(45deg);
        }

        .status-item:hover::before {
            opacity: 1;
        }

        .status-item:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        }

        /* 状态项动画延迟 */
        .status-item:nth-child(1) { animation-delay: 0.6s; }
        .status-item:nth-child(2) { animation-delay: 0.7s; }
        .status-item:nth-child(3) { animation-delay: 0.8s; }
        .status-item:nth-child(4) { animation-delay: 0.9s; }
        .status-item:nth-child(5) { animation-delay: 1.0s; }
        .status-item:nth-child(6) { animation-delay: 1.1s; }
        .status-item:nth-child(7) { animation-delay: 1.2s; }
        .status-item:nth-child(8) { animation-delay: 1.3s; }

        .status-label {
            font-weight: 600;
            display: block;
            margin-bottom: 4px;
            opacity: 0.8;
        }

        .status-value {
            display: block;
            font-size: 14px;
            animation: countUp 1s ease-out;
        }

        @keyframes countUp {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .collapsible-section {
            margin: 24px 16px 16px;
            border-radius: var(--radius-medium);
            overflow: hidden;
            backdrop-filter: var(--blur-default);
            transition: var(--transition-default);
        }

        .collapsible-header {
            padding: 16px 20px;
            cursor: pointer;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-weight: 600;
            transition: var(--transition-default);
            position: relative;
            background: var(--border-color);
        }

        .collapsible-header::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 20px;
            right: 20px;
            height: 1px;
            background: currentColor;
            opacity: 0.1;
            transform: scaleX(0);
            transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .collapsible-section.expanded .collapsible-header::after {
            transform: scaleX(1);
        }

        .collapsible-header:hover {
            opacity: 0.8;
            padding-left: 24px;
        }

        .collapsible-arrow {
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
