            currentTheme: 'day',

            init() {
                this.loadSavedTheme();
                return this;
            },

            loadSavedTheme() {
                this.currentTheme = localStorage.getItem(this.THEME_KEY) || 'day';
                this.applyTheme(this.currentTheme);
            },

            applyTheme: Utils.debounce(function(theme) {
                Utils.raf(() => {
                    DOM.container.className = `story-container theme-${theme}`;
                    this.updateActiveButton(theme);
                    localStorage.setItem(this.THEME_KEY, theme);
                    this.currentTheme = theme;
                });
            }, 100),

            updateActiveButton(theme) {
                DOM.themeButtons.forEach(btn => {
                    btn.classList.toggle('active', btn.dataset.theme === theme);
                });
            },

            handleThemeClick(button) {
                const theme = button.dataset.theme;
                if (theme !== this.currentTheme) {
                    this.applyTheme(theme);
                }
            }
        };

        const CollapsibleManager = {
            isAnimating: false,
            isExpanded: false,

            init() {
                this.isExpanded = DOM.collapsibleSection.classList.contains('expanded');
                return this;
            },

            toggle: Utils.debounce(function() {
                if (this.isAnimating) return;

                this.isAnimating = true;

                Utils.raf(() => {
                    if (!this.isExpanded) {
                        this.expand();
                    } else {
                        this.collapse();
                    }
                });
            }, 150),

            expand() {
                DOM.collapsibleContent.style.maxHeight = DOM.collapsibleInner.scrollHeight + 'px';
                DOM.collapsibleSection.classList.add('expanded');
                this.isExpanded = true;

                setTimeout(() => {
                    this.isAnimating = false;
                    DOM.collapsibleContent.style.maxHeight = 'none';
                }, 800);
            },

            collapse() {
                DOM.collapsibleContent.style.maxHeight = DOM.collapsibleContent.scrollHeight + 'px';
                DOM.collapsibleContent.offsetHeight; 
                DOM.collapsibleContent.style.maxHeight = '0';
                DOM.collapsibleSection.classList.remove('expanded');
                this.isExpanded = false;

                setTimeout(() => {
                    this.isAnimating = false;
                }, 800);
            }
        };

        const OptionsManager = {
            handleClick: Utils.throttle(function(button) {
                const optionText = button.textContent.trim();

                button.classList.add('pressed');
                setTimeout(() => button.classList.remove('pressed'), 150);

                this.triggerQuickReply(optionText);
            }, 300),

            triggerQuickReply(text) {
                if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;

                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${text}|/trigger`);
                } else {
                    console.log('SillyTavern environment not detected. Would send:', text);
                }
            }
        };

        const AnimationObserver = {
            observer: null,

            init() {
                if (!('IntersectionObserver' in window)) return this;

                this.observer = new IntersectionObserver(
                    this.handleIntersection.bind(this),
                    {
                        threshold: 0.1,
                        rootMargin: '50px'
                    }
                );

                this.observeElements();
                return this;
            },

            handleIntersection(entries) {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        Utils.raf(() => {
                            entry.target.classList.add('animate');
                        });
                        this.observer.unobserve(entry.target);
                    }
                });
            },

            observeElements() {
                [...DOM.statusItems, ...DOM.optionButtons].forEach(el => {
                    this.observer.observe(el);
                });
            }
        };

        const EventManager = {
            init() {
                document.addEventListener('click', this.handleGlobalClick.bind(this));
                return this;
            },

            handleGlobalClick(e) {
                const target = e.target;

                if (target.classList.contains('theme-btn')) {
                    e.preventDefault();
                    ThemeManager.handleThemeClick(target);
                }

                if (target.classList.contains('option-btn')) {
                    e.preventDefault();
                    OptionsManager.handleClick(target);
                }

                if (target.closest('.collapsible-header')) {
                    e.preventDefault();
                    CollapsibleManager.toggle();
                }
            }
        };

