<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            const actualValue = current[0];
            return actualValue !== undefined ? actualValue : defaultValue;
        }
        return current;
    }

    function updateProgressBar(barId, valueId, rawValue, min, max) {
        const progressBar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueId);
        if (!progressBar || !valueDisplay) return;

        let displayValue = String(rawValue);
        let numericValueForBar = min;

        if (displayValue.includes('->')) {
            const parts = displayValue.split('->');
            numericValueForBar = parseFloat(parts[1].trim());
            valueDisplay.innerText = displayValue;
        } else {
            numericValueForBar = parseFloat(displayValue);
            valueDisplay.innerText = displayValue;
        }

        if (isNaN(numericValueForBar)) {
            numericValueForBar = min;
        }

        numericValueForBar = Math.max(min, Math.min(max, numericValueForBar));
        const range = max - min;
        const percentage = range === 0 ? 100 : ((numericValueForBar - min) / range) * 100;
        progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
    }

    function setTextContent(id, value, prefix = '', suffix = '') {
        const element = document.getElementById(id);
        if (element) {
            let displayValue = value;
            if (typeof value === 'boolean') {
                displayValue = value ? '是' : '否';
            }
            element.innerText = `${prefix}${displayValue}${suffix}`;
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据。</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载角色数据。</p>";
                 return;
            }

            setTextContent('world-date', SafeGetValue(characterData, '世界.当前日期', '2023-08-01'));
            setTextContent('world-time', SafeGetValue(characterData, '世界.当前时间', '08:00'));

            updateProgressBar('zhouyuqing-degradation-bar', 'zhouyuqing-degradation', SafeGetValue(characterData, '周语晴.背德值', 0), 0, 200);
            updateProgressBar('majunwei-desire-bar', 'majunwei-desire', SafeGetValue(characterData, '马俊伟.欲望值', 0), 0, 200);

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
        updateToggleButton();
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        if (!content) return;
        const isExpanded = !content.classList.contains('expanded');
        content.classList.toggle('expanded', isExpanded);
        element.classList.toggle('expanded-header', isExpanded);
        element.querySelector('.arrow').innerText = isExpanded ? '▲' : '▼';
        updateToggleButton();
    }

    function toggleAllSections() {
        const sections = document.querySelectorAll('.section');
        const shouldExpand = Array.from(sections).some(section => {
            const content = section.querySelector('.section-content');
            return !content.classList.contains('expanded');
        });

        sections.forEach(section => {
            const header = section.querySelector('.section-header');
            const content = section.querySelector('.section-content');
            if (header && content) {
                content.classList.toggle('expanded', shouldExpand);
                header.classList.toggle('expanded-header', shouldExpand);
                header.querySelector('.arrow').innerText = shouldExpand ? '▲' : '▼';
            }
        });
        updateToggleButton();
    }

    function updateToggleButton() {
        const toggleBtn = document.getElementById('toggle-all-btn');
        if (!toggleBtn) return;

        const isAllExpanded = Array.from(document.querySelectorAll('.section-content')).every(content => content.classList.contains('expanded'));

        if (isAllExpanded) {
            toggleBtn.innerHTML = '🔼';
            toggleBtn.title = '全部收起';
        } else {
            toggleBtn.innerHTML = '🔽';
            toggleBtn.title = '全部展开';
        }
    }

    function toggleTheme() {
        const body = document.body;
        const icon = document.getElementById('theme-icon');
        const isDark = body.classList.toggle('dark-theme');
        icon.innerText = isDark ? '☀️' : '🌙';
        localStorage.setItem('theme', isDark ? 'dark' : 'light');
    }

    function loadTheme() {
        const savedTheme = localStorage.getItem('theme') || (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
        if (savedTheme === 'dark') {
            document.body.classList.add('dark-theme');
            document.getElementById('theme-icon').innerText = '☀️';
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        loadTheme();
        initDisplay();
    });
</script>
</body>
</html>
